package com.abhishek.ecommerce.payment;import jakarta.persistence.*;import java.math.BigDecimal;import java.util.UUID;@Entity public class Payment{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;String orderId,userId;BigDecimal amount;String status;public UUID getId(){return id;}public String getOrderId(){return orderId;}public void setOrderId(String v){orderId=v;}public void setUserId(String v){userId=v;}public void setAmount(BigDecimal v){amount=v;}public void setStatus(String v){status=v;}}